/* Session Intelligence 4.0: DST-aware clocks, session ranges and conservative setup evidence */
const SESSION_ENGINE=new window.JPTISessionIntelligence.SessionIntelligenceEngine({historyLimit:1200});
let latestSessionResult=null;
function renderSessionIntelligence(){
 const el=$("#sessionclock");if(!el)return;
 const now=new Date(),snap=SESSION_ENGINE.snapshot(now),active=snap.active;
 el.innerHTML='<div class="sessionclock-head"><div><small>ACTIVE SESSION</small><strong>'+(active?active.name:'OFF-SESSION')+'</strong><span>'+(active?active.localTime+' · '+active.zone:'No configured market window active')+'</span></div><div><small>UTC REFERENCE</small><strong>'+now.toLocaleTimeString("en-GB",{timeZone:"UTC",hour12:false})+'</strong><span>'+now.toISOString().slice(0,10)+'</span></div></div><div class="sessionchips">'+snap.all.map(s=>'<div class="sessionchip '+(s.active?'active':'')+'"><b>'+s.name+'</b><span>'+s.localTime+'</span><small>'+s.open+'–'+s.close+' '+s.zone.split('/').at(-1)+'</small></div>').join('')+'</div>';
 const r=SESSION_ENGINE.getRange(now),setup=latestSessionResult?.setup,perf=SESSION_ENGINE.performance(),p=active?perf[active.id]:null,ev=SESSION_ENGINE.getEvents(5);
 $("#sessionrange").innerHTML=r?'<div class="sessionmetrics"><div><small>SESSION HIGH</small><b>'+f(r.high)+'</b></div><div><small>SESSION LOW</small><b>'+f(r.low)+'</b></div><div><small>RANGE</small><b>'+f(r.high-r.low)+'</b></div><div><small>BARS</small><b>'+r.bars+'</b></div></div>':'<div class="empty">Range begins when a candle is observed during an active session.</div>';
 $("#sessionsetup").textContent=setup?setup.session+' · '+setup.type+' · '+setup.direction.toUpperCase()+' · '+setup.score+'/100 · '+setup.confidence:'No current setup candidate. Recent candle structure is being monitored.';
 $("#sessionalpha").textContent=active?(p.trades+' recorded outcomes · '+(p.winRate===null?'no win-rate sample':(p.winRate*100).toFixed(1)+' observed win rate')+' · '+p.sampleQuality):'No active session';
 $("#sessionevents").innerHTML=ev.length?ev.map(x=>'<div class="sessionevent"><time>'+new Date(x.ts).toLocaleTimeString()+'</time><b>'+x.session+'</b><span>'+x.detail+'</span></div>').join(''):'<div class="empty">Session transitions and setup candidates will appear here.</div>';
}
function updateSessionEngine(candle){
 const key=[S.ex,S.kind,S.symbol,S.tf,candle.time].join(":");if(SESSION_ENGINE.lastObservedKey===key)return;SESSION_ENGINE.lastObservedKey=key;
 const context=[S.ex,S.kind,S.symbol,S.tf].join(":");if(SESSION_ENGINE.contextKey!==context){SESSION_ENGINE.contextKey=context;SESSION_ENGINE.setContext({exchange:S.ex,market:S.kind,symbol:S.symbol,timeframe:S.tf})}
 latestSessionResult=SESSION_ENGINE.observeCandle(candle);
 renderSessionIntelligence();
 if(latestSessionResult?.setup){const ev=latestSessionResult.setup;$("#sessionalpha").title=JSON.stringify(SESSION_ENGINE.alphaEvidence(ev))}
}


function loadSessionOutcomes(){try{const rows=JSON.parse(localStorage.getItem("jpti-session-outcomes")||"[]");rows.forEach(x=>{try{SESSION_ENGINE.recordOutcome(x)}catch{}})}catch{}}
function saveSessionOutcome(){const row={sessionId:$("#outcomesession").value,result:$("#outcomeresult").value,rMultiple:$("#outcomeresult").value==="loss"?-Math.abs(Number($("#outcomer").value)||1):$("#outcomeresult").value==="breakeven"?0:Math.abs(Number($("#outcomer").value)||1),symbol:S.symbol,market:S.kind,exchange:S.ex,ts:Date.now()};SESSION_ENGINE.recordOutcome(row);if(typeof S5!=='undefined')S5.recordOutcome({setupId:'session-outcome-'+row.ts,ts:row.ts,session:row.sessionId,window:row.sessionId,setup:row.symbol+'-'+row.market,r:row.rMultiple,symbol:row.symbol,result:row.result});const rows=JSON.parse(localStorage.getItem("jpti-session-outcomes")||"[]");rows.push(row);localStorage.setItem("jpti-session-outcomes",JSON.stringify(rows.slice(-1000)));$("#outcomestatus").textContent=rows.length+" outcomes saved locally · Alpha gate "+(SESSION_ENGINE.performance()[row.sessionId].trades>=30?"eligible":"30 required per session");renderSessionIntelligence();score()}
$("#recordoutcome").onclick=saveSessionOutcome;loadSessionOutcomes();
setInterval(renderSessionIntelligence,1000);renderSessionIntelligence();
