const S5=new window.JPTISession5.SessionIntelligence5();
const S5APIS=[
{name:"Bitget",url:"https://api.bitget.com/api/v2/spot/market/tickers?symbol=BTCUSDT"},
{name:"Binance",url:"https://api.binance.com/api/v3/ping"},
{name:"Bybit",url:"https://api.bybit.com/v5/market/time"},
{name:"OKX",url:"https://www.okx.com/api/v5/public/time"},
{name:"CoinGecko",url:"https://api.coingecko.com/api/v3/ping"},
{name:"DexScreener",url:"https://api.dexscreener.com/latest/dex/search?q=bitcoin"},
{name:"DeFiLlama",url:"https://api.llama.fi/protocols"},
{name:"Alternative.me Fear & Greed",url:"https://api.alternative.me/fng/?limit=1"},
{name:"Coinbase",url:"https://api.exchange.coinbase.com/products/BTC-USD/ticker"},
{name:"Kraken",url:"https://api.kraken.com/0/public/Ticker?pair=XBTUSD"}
];
async function S5probe(){const el=$("#s5feeds");if(!el)return;el.innerHTML="";const results=await Promise.all(S5APIS.map(async api=>{const start=Date.now();try{const res=await fetch(api.url,{signal:AbortSignal.timeout(7000),cache:"no-store"});S5.updateFeed(api.name,{ts:Date.now(),ok:res.ok,latency:Date.now()-start,error:res.ok?null:"HTTP "+res.status});return{name:api.name,ok:res.ok,ms:Date.now()-start,status:res.status}}catch(err){S5.updateFeed(api.name,{ts:Date.now(),ok:false,latency:Date.now()-start,error:String(err).slice(0,120)});return{name:api.name,ok:false,ms:Date.now()-start,status:"blocked/CORS/timeout"}}}));el.innerHTML=results.map(x=>'<div class="s5-feed"><b>'+x.name+'</b><span class="'+(x.ok?'positive':'negative')+'">'+(x.ok?'ONLINE':'UNAVAILABLE')+'</span><small>'+x.status+' · '+x.ms+' ms</small></div>').join("");}
function S5render(){const p=$("#s5perf"),d=$("#s5decay"),a=$("#s5audit"),rp=$("#s5replay");if(!p)return;const e=S5.expectancy();p.innerHTML='<div class="s5stats"><div><small>Recorded outcomes</small><strong>'+e.trades+'</strong></div><div><small>Win rate</small><strong>'+(e.winRate===null?'—':(e.winRate*100).toFixed(1)+'%')+'</strong></div><div><small>Expectancy</small><strong>'+(e.expectancy===null?'—':e.expectancy.toFixed(3)+' R')+'</strong></div><div><small>Net R</small><strong>'+e.netR.toFixed(2)+'</strong></div><div><small>Profit factor</small><strong>'+(e.profitFactor===null?'—':e.profitFactor.toFixed(2))+'</strong></div></div>';
const decay=S5.decay(),rank=S5.rankWindows({minimumSample:5});d.innerHTML='<h4>Setup decay</h4>'+Object.entries(decay).map(([k,v])=>'<div class="s5-row">'+k+' <span>'+((v.recentExpectancy??0).toFixed(2))+'R recent · '+(v.decaying?'DECAY':'stable / sample-limited')+'</span></div>').join("")+'<h4>Time windows</h4>'+rank.map((x,i)=>'<div class="s5-row">'+(i+1)+'. '+x.window+' <span>'+(x.expectancy===null?'n/a':x.expectancy.toFixed(2)+'R')+' · '+x.trades+' trades</span></div>').join("");
const events=S5.events.slice(-30).reverse();a.innerHTML=events.length?events.map(x=>'<div class="s5-row"><time>'+new Date(x.ts).toLocaleString()+'</time><b>'+x.type+'</b><span>'+x.symbol+' '+x.session+' '+(x.falseSweep?'false sweep tagged':'')+'</span></div>').join(""):"No events collected yet. Use a connected feed or record outcomes/events from session signals.";
rp.innerHTML=S5.replay.events.length?'<p>Replay cursor: '+S5.replay.cursor+'/'+S5.replay.events.length+'</p><pre>'+JSON.stringify(S5.replay.events[S5.replay.cursor-1]||S5.replay.events[0],null,2)+'</pre>':'Replay is empty. Events are captured when the 5.0 collector receives signals.'}
$("#s5refresh").onclick=S5probe;$("#s5export").onclick=()=>{const data=JSON.stringify(S5.exportData(),null,2);const blob=new Blob([data],{type:"application/json"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download="jpti-session-intelligence-5.json";link.click();URL.revokeObjectURL(url)};
$("#s5riskcalc").onclick=()=>{const v=S5.survival({equity:+$("#s5equity").value,riskPct:+$("#s5risk").value,dailyLossPct:+$("#s5loss").value,drawdownPct:+$("#s5dd").value});$("#s5riskout").innerHTML='<p>Risk/trade: '+v.riskPerTrade.toFixed(2)+' · '+(v.blocked?'LIMIT BREACHED':'Within configured limits')+'</p>'};
$("#s5reset").onclick=()=>{S5.setReplay();S5render()};$("#s5step").onclick=()=>{if(!S5.replay.events.length)S5.setReplay();const x=S5.replayStep();$("#s5replay").textContent=x?JSON.stringify(x,null,2):"Replay complete";S5render()};
const s5time=$("#s5seek");if(s5time)s5time.onchange=()=>{const ts=Date.parse(s5time.value);if(Number.isFinite(ts)){S5.setReplay();S5.replaySeek(ts);S5render()}};
S5.setReplay();S5probe();S5render();

async function S5persist(record){try{const r=await fetch('/api/session5',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(record)});if(!r.ok)throw Error('HTTP '+r.status);return await r.json()}catch(e){return{stored:false,error:String(e)}}}
async function S5restore(){try{const r=await fetch('/api/session5?limit=500');if(!r.ok)return;const d=await r.json();for(const row of (d.records||[]).reverse()){const p=row.payload;if(row.record_type==='event'&&!S5.events.some(x=>x.id===p.id))S5.events.push(p);if(row.record_type==='outcome'&&!S5.outcomes.some(x=>x.setupId===p.setupId))S5.outcomes.push(p)}S5render()}catch{}}
const s5ccxtstatus=$('#s5ccxt-status'),s5ccxtout=$('#s5ccxt-out');
function s5ccxtReady(){return window.JPTICCXT&&window.JPTICCXT.init()}
$('#s5ccxt-check').onclick=async()=>{if(!s5ccxtReady()){s5ccxtstatus.textContent='Native exchange adapter unavailable in this browser.';return}const ex=$('#s5ccxt-ex').value;s5ccxtstatus.textContent='Loading markets and checking '+ex+'…';const result=await window.JPTICCXT.test(ex);s5ccxtstatus.textContent=result.ok?'Connected to public '+ex+' market metadata · '+result.latency+'ms':'Connection error: '+result.error;S5.updateFeed('CCXT '+ex,{ts:result.checkedAt,ok:result.ok,latency:result.latency,error:result.error});S5render()};
$('#s5ccxt-data').onclick=async()=>{if(!s5ccxtReady()){s5ccxtstatus.textContent='Native exchange adapter unavailable.';return}const ex=$('#s5ccxt-ex').value,sym=$('#s5ccxt-symbol').value,tf=$('#s5ccxt-tf').value;s5ccxtstatus.textContent='Loading public ticker, candles, order book and trades…';try{const [ticker,candles,book,trades]=await Promise.all([JPTICCXT.ticker(ex,sym),JPTICCXT.candles(ex,sym,tf,100),JPTICCXT.book(ex,sym,20),JPTICCXT.trades(ex,sym,50)]);const result={exchange:ex,symbol:sym,timeframe:tf,ticker,candleCount:candles.length,latestCandle:candles.at(-1),book:{bids:book.bids.slice(0,5),asks:book.asks.slice(0,5)},recentTrades:trades.slice(-10)};s5ccxtout.textContent=JSON.stringify(result,null,2);s5ccxtstatus.textContent='Exchange public data received successfully';const event=S5.recordEvent({type:'ccxt-market-snapshot',ts:Date.now(),symbol:sym,session:SESSION_ENGINE.current?.id,source:'CCXT '+ex,features:{ticker,candleCount:candles.length,topBid:book.bids[0],topAsk:book.asks[0]}});S5persist({type:'event',id:event.id,symbol:sym,session:event.session,payload:event,created_at:new Date(event.ts).toISOString()});S5render()}catch(e){s5ccxtstatus.textContent='Market fetch failed: '+String(e.message||e);S5.updateFeed('CCXT '+ex,{ts:Date.now(),ok:false,error:String(e)});S5render()}};
let s5streamActive=false;
$('#s5ccxt-stream').onclick=()=>{
 if(!s5ccxtReady()){s5ccxtstatus.textContent='Native exchange adapter unavailable.';return}
 if(s5streamActive){JPTICCXT.disconnect();s5streamActive=false;$('#s5ccxt-stream').textContent='Start live trades stream';s5ccxtstatus.textContent='Live stream stopped';return}
 const ex=$('#s5ccxt-ex').value,sym=$('#s5ccxt-symbol').value;
 s5streamActive=true;$('#s5ccxt-stream').textContent='Stop live stream';
 JPTICCXT.stream(ex,sym,{onStatus:(state,msg)=>{s5ccxtstatus.textContent='Native '+ex+' stream: '+state+(msg?' · '+msg:'');if(state==='offline'||state==='error')s5ccxtstatus.textContent+=' · use REST load for fallback'},onTrade:t=>{const ev=S5.recordEvent({type:'live-exchange-trade',ts:t.ts,symbol:sym,session:SESSION_ENGINE.current?.id,price:t.price,source:'Native WebSocket · '+ex,features:{tradeSize:t.size,side:t.side}});S5persist({type:'event',id:ev.id,symbol:sym,session:ev.session,payload:ev,created_at:new Date(ev.ts).toISOString()});s5ccxtout.textContent=JSON.stringify({stream:ex,symbol:sym,lastTrade:t,events:S5.events.length},null,2);S5render()}});
};
async function S5pollLiquidity(){try{const timeline=LBE.timeline(12);for(const item of timeline){const id='lbe-'+item.ts+'-'+item.type+'-'+(item.symbol||S.symbol);if(S5.events.some(e=>e.id===id))continue;const ev=S5.recordEvent({id,type:item.type,ts:item.ts,symbol:item.symbol||S.symbol,session:SESSION_ENGINE.current?.id,price:item.price,level:item.price,source:'Liquidity Footprint Engine',features:item});S5persist({type:'event',id:ev.id,symbol:ev.symbol,session:ev.session,payload:ev,created_at:new Date(ev.ts).toISOString()})}S5render()}catch{}}
const S5originalSave=$('#recordoutcome').onclick;$('#recordoutcome').onclick=()=>{S5originalSave?.();const outcome=S5.outcomes.at(-1);if(outcome)S5persist({type:'outcome',id:outcome.setupId,symbol:outcome.symbol,session:outcome.session,payload:outcome,created_at:new Date(outcome.ts).toISOString()})};
S5restore();S5pollLiquidity();setInterval(S5pollLiquidity,5000);

